package com.minewaku.chatter.identityaccess.infrastructure.user;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import org.bouncycastle.crypto.generators.Argon2BytesGenerator; import org.bouncycastle.crypto.params.Argon2Parameters; import org.springframework.stereotype.Component; import com.minewaku.chatter.identityaccess.user.internal.model.*; import com.minewaku.chatter.identityaccess.user.internal.port.PasswordHasher;
@Component public class Argon2PasswordHasher implements PasswordHasher { private static final SecureRandom R=new SecureRandom(); public PasswordHash hash(PlainPassword p){byte[] salt=new byte[16];R.nextBytes(salt);char[] raw=p.characters();try{return new PasswordHash("argon2id",Base64.getEncoder().encodeToString(derive(raw,salt)),salt);}finally{Arrays.fill(raw,'\0');}} private byte[] derive(char[] raw,byte[] salt){Argon2Parameters ps=new Argon2Parameters.Builder(Argon2Parameters.ARGON2_id).withSalt(salt).withIterations(3).withMemoryAsKB(65536).withParallelism(1).build();byte[] out=new byte[32];Argon2BytesGenerator g=new Argon2BytesGenerator();g.init(ps);g.generateBytes(raw,out);return out;} }